using System;using System.IO;using System.Linq;using System.Reflection;using UnityEditor;using UnityEngine;
namespace MashBoxSDK.AnimationStudio {
public static class StudioHolePunchVolumePreviewValidation {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
 static AnimationStudioWindow owner;static MashBoxStudioViewport view;static StudioModelDocument document;static StudioModelEditor editor;static double end;static int paints;
 static void Set(object o,string n,object v)=>o.GetType().GetField(n,F).SetValue(o,v);
 static object Call(object o,string n,params object[] a)=>o.GetType().GetMethod(n,F).Invoke(o,a);
 public static void Begin(){if(!Application.dataPath.Replace('\\','/').EndsWith("/HolePuncher/Project/Assets"))throw new Exception("Disposable project only");try{
 owner=ScriptableObject.CreateInstance<AnimationStudioWindow>();Set(owner,"modelingMode",true);Set(owner,"paintingMode",false);Set(owner,"clothMode",false);document=ScriptableObject.CreateInstance<StudioModelDocument>();
 var cube=(StudioModelDocument.Node)typeof(StudioHolePunchValidation).GetMethod("Cube",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,null);cube.name="Volume preview";document.nodes.Add(cube);Set(owner,"modelDocument",document);
 view=ScriptableObject.CreateInstance<MashBoxStudioViewport>();view.dockableHost=!StudioSettings.Current.floatingStudioWindow;Set(owner,"viewport",view);view.position=new Rect(30,30,1300,850);if(view.dockableHost)view.Show();else view.ShowUtility();Call(owner,"OpenViewport");view.SelectViewportCamera(1);view.EditingView.LookAtDirect(Vector3.zero,Quaternion.Euler(20,-35,0),3);
 editor=owner.ToolbarModelEditor;Set(editor,"holePunchRadius",.6f);Set(editor,"holePunchDepth",2.6f);Set(editor,"holePunchNormal",Vector3.back);Set(editor,"holePunchCenter",Vector3.back);Set(editor,"holePunchSides",16);Set(editor,"holePunchLimitDepth",true);
 SceneView.duringSceneGui+=Draw;end=EditorApplication.timeSinceStartup+5;EditorApplication.update+=Tick;view.Repaint();
 }catch(Exception e){Finish(e);}}
 static void Draw(SceneView current){if(current!=view.EditingView)return;var color=Handles.color;var depth=Handles.zTest;try{Call(editor,"DrawHolePunchDepthHandle");if(Event.current.type!=EventType.Repaint)return;paints++;var outline=Enumerable.Range(0,17).Select(i=>Vector3.back+.6f*new Vector3(Mathf.Cos(i*Mathf.PI/8),Mathf.Sin(i*Mathf.PI/8),0)).ToArray();Call(editor,"DrawHolePunchVolume",outline,Matrix4x4.identity);}finally{Handles.color=color;Handles.zTest=depth;}}
 static void Tick(){if(EditorApplication.timeSinceStartup<end)return;try{if(paints==0)throw new Exception("No native overlay repaint");Capture();Finish(null);}catch(Exception e){Finish(e);}}
 static void Capture(){var parent=typeof(EditorWindow).GetField("m_Parent",F).GetValue(view);var rt=new RenderTexture((int)view.position.width,(int)view.position.height,0);rt.Create();var old=RenderTexture.active;var image=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false);try{parent.GetType().GetMethod("GrabPixels",F).Invoke(parent,new object[]{rt,new Rect(0,0,rt.width,rt.height)});RenderTexture.active=rt;image.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);var px=image.GetPixels();var flipped=new Color[px.Length];for(int y=0;y<image.height;y++)Array.Copy(px,y*image.width,flipped,(image.height-1-y)*image.width,image.width);image.SetPixels(flipped);image.Apply();File.WriteAllBytes(Path.GetFullPath(Path.Combine(Application.dataPath,"../../volume-preview.png")),image.EncodeToPNG());}finally{RenderTexture.active=old;UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(image);}}
 static void Finish(Exception e){EditorApplication.update-=Tick;SceneView.duringSceneGui-=Draw;File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../volume-preview-result.txt")),e==null?"PASS native production volume/handle repaint and capture; paints="+paints:"FAIL "+e);if(owner)UnityEngine.Object.DestroyImmediate(owner);if(view)UnityEngine.Object.DestroyImmediate(view);if(document){foreach(var n in document.nodes)if(n.mesh)UnityEngine.Object.DestroyImmediate(n.mesh);UnityEngine.Object.DestroyImmediate(document);}EditorApplication.Exit(e==null?0:1);}
}}
